-- =============================================================================================
-- Hand-written below this line: the maker-checker rule (a second person decides), each risky
-- action allowed only by a matching approval carried out once, credit notes and write-offs
-- within what an invoice still owes, refunds within a payment's unused money, payment reversals
-- only of unallocated, unrefunded payments, reopening a closed period only with an approval,
-- row-level security and grants. See docs/architecture/DATA_MODEL.md section 6 (Controls).
-- New JournalSource values are only used inside function bodies (checked when they run).
-- =============================================================================================

-- What has been taken from a payment (allocations not released, plus refunds) and what has been
-- settled on an invoice (allocations not released, plus credit notes and write-offs).
CREATE FUNCTION app_payment_used(payment uuid) RETURNS numeric
  LANGUAGE sql STABLE
  AS $$
    SELECT coalesce((SELECT sum("amount_minor") FROM "payment_allocations"
                      WHERE "payment_id" = payment AND "released_at" IS NULL), 0)
         + coalesce((SELECT sum("amount_minor") FROM "payment_refunds" WHERE "payment_id" = payment), 0)
  $$;

CREATE FUNCTION app_invoice_settled(invoice uuid) RETURNS numeric
  LANGUAGE sql STABLE
  AS $$
    SELECT coalesce((SELECT sum("amount_minor") FROM "payment_allocations"
                      WHERE "invoice_id" = invoice AND "released_at" IS NULL), 0)
         + coalesce((SELECT sum("amount_minor") FROM "invoice_credits" WHERE "invoice_id" = invoice), 0)
  $$;

GRANT EXECUTE ON FUNCTION app_payment_used(uuid), app_invoice_settled(uuid) TO veyra_app;

-- ---------------------------------------------------------------------------------------------
-- finance_approvals
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "finance_approvals" ADD CONSTRAINT "finance_approvals_reason_trimmed"
  CHECK ("reason" = btrim("reason") AND length("reason") BETWEEN 1 AND 500);
ALTER TABLE "finance_approvals" ADD CONSTRAINT "finance_approvals_note_trimmed"
  CHECK ("decision_note" IS NULL OR ("decision_note" = btrim("decision_note") AND length("decision_note") BETWEEN 1 AND 500));
-- Each action names exactly its own target. coalesce: a NULL comparison must fail the check, not pass it.
ALTER TABLE "finance_approvals" ADD CONSTRAINT "finance_approvals_target"
  CHECK (
    coalesce(CASE "action"
      WHEN 'REVERSE_PAYMENT' THEN "payment_id" IS NOT NULL AND "invoice_id" IS NULL AND "period_id" IS NULL
                                  AND "amount_minor" IS NULL AND "refund_method" IS NULL
      WHEN 'REFUND' THEN "payment_id" IS NOT NULL AND "invoice_id" IS NULL AND "period_id" IS NULL
                         AND "amount_minor" > 0 AND "refund_method" IN ('BANK_TRANSFER', 'CASH', 'CHEQUE')
      WHEN 'WRITE_OFF' THEN "invoice_id" IS NOT NULL AND "payment_id" IS NULL AND "period_id" IS NULL
                            AND "amount_minor" > 0 AND "refund_method" IS NULL
      WHEN 'REOPEN_PERIOD' THEN "period_id" IS NOT NULL AND "payment_id" IS NULL AND "invoice_id" IS NULL
                                AND "amount_minor" IS NULL AND "refund_method" IS NULL
    END, false)
  );
-- Maker-checker: approvals and rejections are by someone other than the requester; only the
-- requester cancels; an approval is carried out at once.
ALTER TABLE "finance_approvals" ADD CONSTRAINT "finance_approvals_decision"
  CHECK (
    ("status" = 'PENDING') = ("decided_at" IS NULL)
    AND ("status" = 'PENDING') = ("decided_by_user_id" IS NULL)
    AND ("status" NOT IN ('APPROVED', 'REJECTED') OR "decided_by_user_id" <> "requested_by_user_id")
    AND ("status" <> 'CANCELLED' OR "decided_by_user_id" = "requested_by_user_id")
    AND ("status" = 'APPROVED') = ("executed_at" IS NOT NULL)
  );

CREATE FUNCTION app_finance_approval_insert_check() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF NEW."status" <> 'PENDING' THEN
    RAISE EXCEPTION 'approval requests start pending' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "finance_approvals_insert_check"
  BEFORE INSERT ON "finance_approvals"
  FOR EACH ROW EXECUTE FUNCTION app_finance_approval_insert_check();

-- Decided once; the request itself never changes.
CREATE FUNCTION app_finance_approval_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF OLD."status" <> 'PENDING'
     OR (NEW."organisation_id", NEW."property_id", NEW."action", NEW."payment_id", NEW."invoice_id",
         NEW."period_id", NEW."amount_minor", NEW."refund_method", NEW."reason",
         NEW."requested_by_user_id", NEW."created_at")
        IS DISTINCT FROM
        (OLD."organisation_id", OLD."property_id", OLD."action", OLD."payment_id", OLD."invoice_id",
         OLD."period_id", OLD."amount_minor", OLD."refund_method", OLD."reason",
         OLD."requested_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'approval request % is decided once and never changes', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "finance_approvals_guard"
  BEFORE UPDATE ON "finance_approvals"
  FOR EACH ROW EXECUTE FUNCTION app_finance_approval_guard();

-- The approval an action relies on: APPROVED, of that action and target. (Each approval is used
-- once: the action tables hold approval_id unique.)
CREATE FUNCTION app_require_approval(approval uuid, wanted "FinanceApprovalAction", payment uuid,
                                     invoice uuid, amount bigint) RETURNS void
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF approval IS NULL OR NOT EXISTS (
    SELECT 1 FROM "finance_approvals"
     WHERE "id" = approval AND "status" = 'APPROVED' AND "action" = wanted
       AND "payment_id" IS NOT DISTINCT FROM payment AND "invoice_id" IS NOT DISTINCT FROM invoice
       AND "amount_minor" IS NOT DISTINCT FROM amount
  ) THEN
    RAISE EXCEPTION '% needs an approval by a second person', lower(replace(wanted::text, '_', ' '))
      USING ERRCODE = 'check_violation';
  END IF;
END
$$;

