-- invoice_credits
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "invoice_credits" ADD CONSTRAINT "invoice_credits_amount_positive" CHECK ("amount_minor" > 0);
ALTER TABLE "invoice_credits" ADD CONSTRAINT "invoice_credits_reason_trimmed"
  CHECK ("reason" = btrim("reason") AND length("reason") BETWEEN 1 AND 500);
ALTER TABLE "invoice_credits" ADD CONSTRAINT "invoice_credits_kind_consistent"
  CHECK (
    ("kind" = 'CREDIT_NOTE') = ("credit_number" IS NOT NULL)
    AND ("kind" = 'CREDIT_NOTE') = ("line_number" IS NOT NULL)
    AND ("kind" = 'WRITE_OFF') = ("approval_id" IS NOT NULL)
  );

-- A credit reduces what an ISSUED invoice still owes, never below zero (advisory lock on the
-- invoice, shared with allocations); a credit note stays within its line; its posted entry
-- credits exactly the amount to the unit's receivables; a write-off needs its approval.
CREATE FUNCTION app_invoice_credit_insert_check() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  inv record;
  entry record;
  credited numeric;
  line_amount bigint;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('veyra.invoice:' || NEW."invoice_id"::text, 0));
  SELECT "status", "total_minor" INTO inv FROM "invoices" WHERE "id" = NEW."invoice_id";
  IF inv."status" IS DISTINCT FROM 'ISSUED' THEN
    RAISE EXCEPTION 'only issued invoices are credited' USING ERRCODE = 'check_violation';
  END IF;
  IF app_invoice_settled(NEW."invoice_id") + NEW."amount_minor" > inv."total_minor" THEN
    RAISE EXCEPTION 'the credit is more than the invoice still owes' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."kind" = 'CREDIT_NOTE' THEN
    SELECT "amount_minor" INTO line_amount FROM "invoice_lines"
     WHERE "invoice_id" = NEW."invoice_id" AND "line_number" = NEW."line_number";
    IF line_amount IS NULL THEN
      RAISE EXCEPTION 'the invoice has no line %', NEW."line_number" USING ERRCODE = 'check_violation';
    END IF;
    SELECT coalesce(sum("amount_minor"), 0) INTO credited FROM "invoice_credits"
     WHERE "invoice_id" = NEW."invoice_id" AND "line_number" = NEW."line_number";
    IF credited + NEW."amount_minor" > line_amount THEN
      RAISE EXCEPTION 'the credit note is more than the line' USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    PERFORM app_require_approval(NEW."approval_id", 'WRITE_OFF', NULL, NEW."invoice_id", NEW."amount_minor");
  END IF;
  SELECT "status", "source"::text AS source, "entry_date" INTO entry
    FROM "journal_entries" WHERE "id" = NEW."journal_entry_id";
  IF entry."status" IS DISTINCT FROM 'POSTED' OR entry."source" <> NEW."kind"::text
     OR entry."entry_date" <> NEW."credited_on" THEN
    RAISE EXCEPTION 'a credit needs its posted entry of the same kind and date' USING ERRCODE = 'check_violation';
  END IF;
  SELECT coalesce(sum(l."credit_minor") - sum(l."debit_minor"), 0) INTO credited
    FROM "journal_lines" l JOIN "ledger_accounts" a ON a."id" = l."account_id"
   WHERE l."entry_id" = NEW."journal_entry_id" AND a."system_key" = 'RECEIVABLES' AND l."unit_id" = NEW."unit_id";
  IF credited <> NEW."amount_minor" THEN
    RAISE EXCEPTION 'a credit entry must credit the amount to the unit''s receivables' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."kind" = 'CREDIT_NOTE' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('veyra.credit_notes:' || NEW."property_id"::text, 0));
    SELECT coalesce(max("credit_number"), 0) + 1 INTO NEW."credit_number"
      FROM "invoice_credits" WHERE "property_id" = NEW."property_id";
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "invoice_credits_insert_check"
  BEFORE INSERT ON "invoice_credits"
  FOR EACH ROW EXECUTE FUNCTION app_invoice_credit_insert_check();

-- ---------------------------------------------------------------------------------------------
-- payment_refunds and payment_reversals
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "payment_refunds" ADD CONSTRAINT "payment_refunds_amount_positive" CHECK ("amount_minor" > 0);
ALTER TABLE "payment_refunds" ADD CONSTRAINT "payment_refunds_method"
  CHECK ("method" IN ('BANK_TRANSFER', 'CASH', 'CHEQUE'));

-- A refund pays back unused money of a payment that is not reversed (advisory lock on the payment,
-- shared with allocations); its posted entry debits exactly the amount from the unit's credit.
CREATE FUNCTION app_payment_refund_insert_check() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  pay_amount bigint;
  entry record;
  debited numeric;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('veyra.payment:' || NEW."payment_id"::text, 0));
  PERFORM app_require_approval(NEW."approval_id", 'REFUND', NEW."payment_id", NULL, NEW."amount_minor");
  IF NOT EXISTS (
    SELECT 1 FROM "finance_approvals" WHERE "id" = NEW."approval_id" AND "refund_method" = NEW."method"
  ) THEN
    RAISE EXCEPTION 'the refund method differs from the one approved' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM "payment_reversals" WHERE "payment_id" = NEW."payment_id") THEN
    RAISE EXCEPTION 'a reversed payment cannot be refunded' USING ERRCODE = 'check_violation';
  END IF;
  SELECT "amount_minor" INTO pay_amount FROM "payments" WHERE "id" = NEW."payment_id";
  IF app_payment_used(NEW."payment_id") + NEW."amount_minor" > pay_amount THEN
    RAISE EXCEPTION 'the refund is more than the payment''s unused money' USING ERRCODE = 'check_violation';
  END IF;
  SELECT "status", "source"::text AS source, "entry_date" INTO entry
    FROM "journal_entries" WHERE "id" = NEW."journal_entry_id";
  IF entry."status" IS DISTINCT FROM 'POSTED' OR entry."source" <> 'REFUND' OR entry."entry_date" <> NEW."refunded_on" THEN
    RAISE EXCEPTION 'a refund needs its posted refund entry of the same date' USING ERRCODE = 'check_violation';
  END IF;
  SELECT coalesce(sum(l."debit_minor") - sum(l."credit_minor"), 0) INTO debited
    FROM "journal_lines" l JOIN "ledger_accounts" a ON a."id" = l."account_id"
   WHERE l."entry_id" = NEW."journal_entry_id" AND a."system_key" = 'UNIT_CREDIT' AND l."unit_id" = NEW."unit_id";
  IF debited <> NEW."amount_minor" THEN
    RAISE EXCEPTION 'a refund entry must debit the amount from the unit''s credit' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "payment_refunds_insert_check"
  BEFORE INSERT ON "payment_refunds"
  FOR EACH ROW EXECUTE FUNCTION app_payment_refund_insert_check();

-- A payment is reversed only when nothing of it is allocated or refunded, by the posted reversal
-- of its own ledger entry.
CREATE FUNCTION app_payment_reversal_insert_check() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  pay_entry uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('veyra.payment:' || NEW."payment_id"::text, 0));
  PERFORM app_require_approval(NEW."approval_id", 'REVERSE_PAYMENT', NEW."payment_id", NULL, NULL);
  IF app_payment_used(NEW."payment_id") > 0 THEN
    RAISE EXCEPTION 'release the payment''s allocations and keep it unrefunded before reversing it'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT "journal_entry_id" INTO pay_entry FROM "payments" WHERE "id" = NEW."payment_id";
  IF NOT EXISTS (
    SELECT 1 FROM "journal_entries"
     WHERE "id" = NEW."journal_entry_id" AND "status" = 'POSTED' AND "reverses_entry_id" = pay_entry
       AND "entry_date" = NEW."reversed_on"
  ) THEN
    RAISE EXCEPTION 'a payment reversal needs the posted reversal of the payment''s entry'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "payment_reversals_insert_check"
  BEFORE INSERT ON "payment_reversals"
  FOR EACH ROW EXECUTE FUNCTION app_payment_reversal_insert_check();

-- Credits, refunds and reversals never change, for any role.
CREATE FUNCTION app_reject_finance_record_change() RETURNS trigger
  LANGUAGE plpgsql
  AS $$ BEGIN RAISE EXCEPTION '% never changes', TG_TABLE_NAME USING ERRCODE = 'insufficient_privilege'; END $$;

DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['invoice_credits', 'payment_refunds', 'payment_reversals'] LOOP
    EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION app_reject_finance_record_change()', t || '_immutable', t);
    EXECUTE format('CREATE TRIGGER %I BEFORE TRUNCATE ON %I FOR EACH STATEMENT EXECUTE FUNCTION app_reject_ledger_truncate()', t || '_no_truncate', t);
  END LOOP;
END
$$;

-- ---------------------------------------------------------------------------------------------
-- Allocations (replaces the Part 3 check): a payment's unused money also excludes refunds, a
-- reversed payment allocates nothing, and an invoice's remaining amount also excludes credits.
-- ---------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION app_payment_allocation_insert_check() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  pay record;
  inv record;
BEGIN
  IF NEW."released_at" IS NOT NULL THEN
    RAISE EXCEPTION 'an allocation is created unreleased' USING ERRCODE = 'check_violation';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('veyra.payment:' || NEW."payment_id"::text, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('veyra.invoice:' || NEW."invoice_id"::text, 0));
  SELECT "paid_by", "tenancy_id", "amount_minor" INTO pay FROM "payments" WHERE "id" = NEW."payment_id";
  SELECT "status", "bill_to", "tenancy_id", "total_minor" INTO inv FROM "invoices" WHERE "id" = NEW."invoice_id";
  IF inv."status" IS DISTINCT FROM 'ISSUED' THEN
    RAISE EXCEPTION 'payments are allocated to issued invoices only' USING ERRCODE = 'check_violation';
  END IF;
  IF pay."paid_by" <> inv."bill_to" OR pay."tenancy_id" IS DISTINCT FROM inv."tenancy_id" THEN
    RAISE EXCEPTION 'a payment pays only invoices addressed to whoever made it'
      USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM "payment_reversals" WHERE "payment_id" = NEW."payment_id") THEN
    RAISE EXCEPTION 'a reversed payment cannot be allocated' USING ERRCODE = 'check_violation';
  END IF;
  IF app_payment_used(NEW."payment_id") + NEW."amount_minor" > pay."amount_minor" THEN
    RAISE EXCEPTION 'the allocation is more than what is left of the payment'
      USING ERRCODE = 'check_violation';
  END IF;
  IF app_invoice_settled(NEW."invoice_id") + NEW."amount_minor" > inv."total_minor" THEN
    RAISE EXCEPTION 'the allocation is more than what is left to pay on the invoice'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM "journal_entries"
     WHERE "id" = NEW."journal_entry_id" AND "status" = 'POSTED' AND "source" = 'ALLOCATION'
  ) THEN
    RAISE EXCEPTION 'an allocation needs a posted allocation entry' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

-- ---------------------------------------------------------------------------------------------
-- Accounting periods (replaces the Part 1 guard): reopening a closed period needs an approval
-- for that period carried out after it was closed (owner decision: maker-checker).
-- ---------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION app_accounting_period_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF (NEW."organisation_id", NEW."property_id", NEW."start_date", NEW."end_date", NEW."created_at")
     IS DISTINCT FROM
     (OLD."organisation_id", OLD."property_id", OLD."start_date", OLD."end_date", OLD."created_at") THEN
    RAISE EXCEPTION 'accounting period % cannot move or change its dates', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD."status" = 'CLOSED' AND NEW."status" = 'OPEN' AND NOT EXISTS (
    SELECT 1 FROM "finance_approvals"
     WHERE "period_id" = OLD."id" AND "action" = 'REOPEN_PERIOD' AND "status" = 'APPROVED'
       AND "executed_at" >= OLD."closed_at"
  ) THEN
    RAISE EXCEPTION 'reopening a closed period needs an approval by a second person'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

-- ---------------------------------------------------------------------------------------------
-- Row-level security and grants.
-- ---------------------------------------------------------------------------------------------
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['finance_approvals', 'invoice_credits', 'payment_refunds', 'payment_reversals'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (organisation_id = app_current_organisation_id())', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR INSERT WITH CHECK (organisation_id = app_current_organisation_id())', t || '_insert', t);
  END LOOP;
END
$$;
CREATE POLICY "finance_approvals_update" ON "finance_approvals" FOR UPDATE
  USING (organisation_id = app_current_organisation_id())
  WITH CHECK (organisation_id = app_current_organisation_id());

REVOKE ALL ON "finance_approvals", "invoice_credits", "payment_refunds", "payment_reversals" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "finance_approvals" TO veyra_app;
GRANT SELECT, INSERT ON "invoice_credits", "payment_refunds", "payment_reversals" TO veyra_app;
